 TEST(ranges_test, vector_char) {
   EXPECT_EQ(fmt::format("{}", std::vector<char>{'a', 'b'}), "['a', 'b']");
 }
+
+TEST(ranges_test, nested_char_ranges) {
+  auto v = std::vector<std::vector<char>>{{'a'}, {'b', '-', 'c'}};
+  EXPECT_EQ(fmt::format("{}", v), "[['a'], ['b', '-', 'c']]");
