+  EXPECT_EQ(fmt::format("{}", nested), "[[['a'], ['b', '-', 'c']]]");
+  EXPECT_EQ(fmt::format("{}", std::vector<std::vector<char>>{{'\n', '\''}}),
+            "[['\\n', '\\'']]");
+  EXPECT_EQ(fmt::format("{}", std::vector<std::vector<std::string>>{{"a\nb"}}),
+            "[[\"a\\nb\"]]");
+}
+
+#ifdef __cpp_lib_ranges
+struct char_range {
+  std::string_view sv;
+
+  template <std::ranges::range R>
+  explicit char_range(R&& r)
+      : sv(std::ranges::data(r), std::ranges::distance(r)) {}
+
+  auto begin() { return sv.begin(); }
+  auto end() { return sv.end(); }
+};
+
+TEST(ranges_test, split_view) {
+  std::string line = "a,b-c,d-e,f";
+  EXPECT_EQ(fmt::format("{}", line | std::views::split(',')),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+TEST(ranges_test, transform_char_range) {
+  std::string line = "a,b-c,d-e,f";
+  auto x = line | std::views::split(',') |
+           std::views::transform([](auto part) { return char_range(part); });
+  EXPECT_EQ(fmt::format("{}", x),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+TEST(ranges_test, transform_split_view) {
+  std::string line = "a,b-c,d-e,f";
+  auto x = line | std::views::split(',') |
+           std::views::transform(std::views::split('-'));
+  EXPECT_EQ(fmt::format("{}", x),
+            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
+}
+#endif  // __cpp_lib_ranges
